```html
<!DOCTYPE html>
<html>
<head>
<style>
  body { margin: 0; font: 14px/1.5 system-ui, sans-serif; color: #e8e2d6; }
  .card { margin: 4px; padding: 14px 16px; border-radius: 14px;
    background: linear-gradient(160deg, #2c2a26, #1d1c1a); border: 1px solid #ffffff1a; }
  h3 { margin: 0 0 10px; font-size: 15px; letter-spacing: .02em; }
  .row { display: grid; grid-template-columns: 64px 1fr 40px; gap: 10px; align-items: center; margin: 6px 0; }
  .bar { height: 8px; border-radius: 99px; background: #ffffff14; overflow: hidden; }
  .fill { height: 100%; border-radius: inherit; transition: width .6s cubic-bezier(.2, .8, .2, 1); }
  .num { text-align: right; font-variant-numeric: tabular-nums; color: #b9b2a5; }
  button { margin-top: 10px; padding: 5px 14px; border: 1px solid #ffffff26; border-radius: 99px;
    background: #ffffff0f; color: inherit; font: inherit; font-size: 13px; cursor: pointer; transition: background .2s; }
  button:hover:not(:disabled) { background: #ffffff1f; }
  button:disabled { opacity: .55; cursor: default; }
</style>
</head>
<body>
  <div class="card">
    <h3>🌲 Glade Sanctuary</h3>
    <div class="row" id="health"><span>Health</span><div class="bar"><div class="fill" style="width:42%;background:#e0705a"></div></div><span class="num">42</span></div>
    <div class="row"><span>Mana</span><div class="bar"><div class="fill" style="width:86%;background:#6aa5e8"></div></div><span class="num">86</span></div>
    <div class="row"><span>Trust</span><div class="bar"><div class="fill" style="width:64%;background:#d9a441"></div></div><span class="num">64</span></div>
    <button type="button">Rest by the spring</button>
  </div>
<script>
  document.querySelector('button').addEventListener('click', (event) => {
    const health = document.querySelector('#health');
    health.querySelector('.fill').style.width = '58%';
    health.querySelector('.num').textContent = '58';
    event.currentTarget.disabled = true;
    event.currentTarget.textContent = 'Rested';
  });
</script>
</body>
</html>
